mapper.select:
SELECT SRVC_CD , WH_CD , IN_NO , IN_EXPECTED_DATE , IN_EXPECTED_NO , IN_EXPECTED_SEQ , VENDOR_CD , VENDOR_NM , PROD_CD , COALESCE(NULLIF(fn_get_prod_nm(SRVC_CD, WH_CD, PROD_CD), ''), '') AS PROD_NM , COALESCE(NULLIF(ORIGINAL_QTY, 0), 0) AS ORIGINAL_QTY , COALESCE(NULLIF(EXPECTED_QTY, 0), 0) AS EXPECTED_QTY , COALESCE(NULLIF(OPEN_QTY, 0), 0) AS OPEN_QTY , COALESCE(NULLIF(TEMP_QTY, 0), 0) AS TEMP_QTY , COALESCE(NULLIF(RECEIVED_QTY, 0), 0) AS RECEIVED_QTY , STATUS , RMK , IN_ZONE_CD , COALESCE(NULLIF(FN_GET_PROD_NM(SRVC_CD, WH_CD, IN_ZONE_CD), ''), '') AS IN_ZONE_NM , COALESCE(NULLIF(WMS.FN_GET_USER_NM(REG_ID),''),'') AS REG_ID , TO_CHAR(REG_DATE,'YYYY-MM-DD') AS REG_DATE , COALESCE(NULLIF(WMS.FN_GET_USER_NM(UPD_ID),''),'') AS UPD_ID , TO_CHAR(UPD_DATE,'YYYY-MM-DD') AS UPD_DATE FROM WMS.TB_RECEIPT_D WHERE 1 = 1 AND SRVC_CD = #{srvcCd} AND WH_CD = #{whCd}
AND IN_NO = #{inNo}
ORDER BY IN_EXPECTED_SEQ
